html, body { height: 100%; }

body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica,
    Arial, sans-serif;
  background:
    radial-gradient(1200px 600px at 20% -10%, #1b2330 0%, transparent 60%),
