  width: 100%;
  max-width: 32rem;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 2rem;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);
}

h1 {
  margin: 0 0 0.5rem 0;
  font-size: 1.5rem;
  font-weight: 600;
}

.lede {
  margin: 0 0 1.5rem 0;
  color: var(--text-muted);
  font-size: 0.95rem;
}

.req { color: var(--accent); margin-left: 0.15rem; }
.optional { color: var(--text-muted); font-weight: 400; font-size: 0.9rem; }

.form-field {
  margin-bottom: 1.25rem;
  display: flex;
  flex-direction: column;
}

label {
  font-weight: 500;
  margin-bottom: 0.4rem;
  font-size: 0.95rem;
}

input {
  font: inherit;
  color: var(--text);
  background-color: var(--surface-2);
  border: 1px solid var(--border-strong);
  border-radius: 6px;
  padding: 0.6rem 0.75rem;
  width: 100%;
  transition: border-color 0.15s, box-shadow 0.15s, background-color 0.15s;
}

input::placeholder { color: var(--text-muted); }

input:hover {
  border-color: #5b6573;
}

input:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
  border-color: var(--focus);
}

input[aria-invalid="true"] {
  border-color: var(--danger);
  background-color: var(--danger-bg);
}

.help-text {
  margin: 0.4rem 0 0 0;
  font-size: 0.85rem;
  color: var(--text-muted);
}

.error-message {
  margin: 0.4rem 0 0 0;
  font-size: 0.875rem;
  color: var(--danger);
  font-weight: 500;
}

button[type="submit"] {
  font: inherit;
  font-weight: 600;
  margin-top: 0.5rem;
  padding: 0.7rem 1.25rem;
  background-color: var(--accent);
  color: #0b1220;
  border: 1px solid var(--accent);
  border-radius: 6px;
  cursor: pointer;
  transition: background-color 0.15s, border-color 0.15s;
}

button[type="submit"]:hover { background-color: var(--accent-hover); border-color: var(--accent-hover); }

button[type="submit"]:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.form-status {
  margin-top: 1rem;
  min-height: 1.25rem;
  font-size: 0.95rem;
  color: var(--accent-hover);
